import { expect, test } from '@playwright/test';
import { ADMIN, masterKey } from '../support/env.js';
import { api } from '../support/shell.js';

test.describe('MK-062 Credentials on the test bench', () => {
  test('62.4 the bench has a master key of its own, so credentials can be stored', async () => {
    // 32 random bytes in base64, generated by the bench for this run.
    expect(Buffer.from(masterKey(), 'base64')).toHaveLength(32);

    const keys = await api(ADMIN, '/api/v1/platform/secrets/keys');
    expect(keys.status).toBe(200);
    expect(keys.body).toMatchObject({ enabled: true });

    const name = `bench-${String(Date.now())}`;
    const stored = await api(ADMIN, '/api/v1/platform/credentials', {
      method: 'POST',
      body: JSON.stringify({ name, kind: 'token', value: 'a token of the bench, 0123' }),
    });
    expect(stored.status).toBe(201);
    expect(stored.body).toMatchObject({ name, kind: 'token', hint: '••••0123' });
  });
});
